CREATE TABLE learning_export_state(singleton INTEGER PRIMARY KEY CHECK(singleton=1),seq INTEGER NOT NULL DEFAULT 1);
INSERT INTO learning_export_state(singleton)VALUES(1);
CREATE TABLE learning_export_previews(id TEXT PRIMARY KEY,hash TEXT NOT NULL,scope_json TEXT NOT NULL,snapshot_json TEXT NOT NULL,state_seq INTEGER NOT NULL,count INTEGER NOT NULL,bytes INTEGER NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE learning_exports(id TEXT PRIMARY KEY,preview_id TEXT NOT NULL REFERENCES learning_export_previews(id),job_id TEXT NOT NULL UNIQUE,request_key TEXT NOT NULL UNIQUE,user_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',path TEXT NOT NULL DEFAULT '',error TEXT NOT NULL DEFAULT '',expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TRIGGER export_state_learning_questions_insert AFTER INSERT ON learning_questions BEGIN UPDATE learning_export_state SET seq=seq+1 WHERE singleton=1; END;
